public void write()
{
    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        FormDataSource formDs = this;
        FormRun formRun = this.formRun();

        RetailDiscountLineThresholdApplying retailDiscountLineThresholdApplying = formDs.cursor();

        InventDim gupInventDimThresholdApplying = formRun.dataSource(formdatasourcestr(RetailPeriodicDiscount, GUPInventDimThresholdApplying)).cursor();
        retailDiscountLineThresholdApplying.InventDimId = InventDim::findOrCreate(gupInventDimThresholdApplying).inventDimId;
    }

    next write();
}
